CAT = "fladjCommercial"; SEG = "COM"
Q = [
("Under the building and personal property coverage form, debris removal pays up to what share of the direct loss plus the deductible?",
 "25 percent", ["5 percent", "10 percent", "50 percent"],
 "The debris removal additional coverage pays up to 25 percent of the direct physical loss plus the deductible, with an extra amount available above that."),
("A commercial building has been vacant for more than 60 straight days when a covered fire occurs. Under the commercial property conditions, the payment is:",
 "Reduced by 15 percent", ["Not made at all", "Paid in full", "Reduced by 50 percent"],
 "The vacancy condition excludes vandalism, sprinkler leakage, glass breakage, water damage and theft after 60 days of vacancy and reduces payment for other covered losses by 15 percent."),
("A warehouse worth $800,000 at the time of loss is insured for $560,000 with an 80 percent coinsurance clause. A $100,000 loss with a $1,000 deductible is paid as:",
 "$86,500", ["$87,500", "$99,000", "$69,000"],
 "Required insurance is 80 percent x $800,000 = $640,000. $560,000 / $640,000 = 0.875; 0.875 x $100,000 = $87,500, less the $1,000 deductible, is $86,500. $69,000 wrongly uses the full $800,000."),
("The special causes of loss form covers:",
 "Any direct loss not excluded", ["Only the perils it lists", "Flood and earthquake too", "Fire and lightning only"],
 "The special form is open perils: it covers risks of direct physical loss unless excluded or limited. Flood and earthquake remain excluded unless endorsed."),
("Business income coverage on a commercial property policy normally starts paying lost income after a waiting period of:",
 "72 hours", ["24 hours", "48 hours", "7 days"],
 "The ISO business income form's period of restoration begins 72 hours after the direct physical loss for business income; extra expense begins immediately."),
("Under the business income form, the period of restoration ends on the date the property:",
 "Should be repaired with due speed", ["Is sold to a new owner", "Passes a final inspection", "Gets a new paying tenant"],
 "The period of restoration ends when the property should be repaired, rebuilt or replaced with reasonable speed and similar quality, or when business resumes elsewhere, whichever is earlier."),
("The extended business income provision pays for:",
 "Lost income after reopening", ["Income lost before the loss", "Costs during a labor strike", "Wages of laid-off workers"],
 "Extended business income continues payments for a set number of days after the property is repaired and operations resume, while the business rebuilds its customer base."),
("Under the building and personal property coverage form, a newly acquired building is covered automatically for up to:",
 "30 days", ["14 days", "60 days", "90 days"],
 "The coverage extension for newly acquired or constructed property ends after 30 days, when the policy expires, or when values are reported, whichever comes first."),
("Under the commercial property vacancy condition, a building under construction or renovation is:",
 "Not considered vacant", ["Vacant after 30 days", "Vacant after 60 days", "Excluded from coverage"],
 "The commercial property conditions state that buildings under construction or renovation are not considered vacant, so the 60-day vacancy rules do not apply."),
("A businessowners policy is designed for:",
 "Small and midsize businesses", ["Large factory operations", "Auto dealers and repair garages", "Farms and ranches"],
 "The BOP packages property, business income and liability for eligible small and midsize businesses such as offices, shops and apartment buildings."),
("On a typical businessowners policy, business income is paid for actual loss sustained for up to:",
 "12 months", ["6 months", "24 months", "30 days"],
 "The ISO businessowners form pays actual loss sustained for up to 12 consecutive months after the direct physical loss, with no dollar limit."),
("Coverage A of the ordinance or law endorsement on a commercial building pays for:",
 "Loss to the undamaged part", ["The cost to demolish", "The higher cost to rebuild", "Lost rental income"],
 "Coverage A pays the value of the undamaged portion that must be torn down by ordinance; Coverage B pays demolition and Coverage C the increased cost of construction."),
]
